import 'package:flutter/material.dart';import '../../../core/network/api_endpoints.dart';import '../../../core/network/dio_client.dart';import '../../../shared/widgets/app_card.dart';
class EnvToolsPage extends StatefulWidget{const EnvToolsPage({super.key});@override State<EnvToolsPage>createState()=>_S();}class _S extends State<EnvToolsPage>{final ids=TextEditingController(),name=TextEditingController(),search=TextEditingController(),replace=TextEditingController();String output='';List<int> get parsed=>ids.text.split(',').map((e)=>int.tryParse(e.trim())).whereType<int>().toList();Future<void>rename()async{await DioClient.instance.dio.put(ApiEndpoints.envsBatchRename,data:{'ids':parsed,if(name.text.trim().isNotEmpty)'name':name.text.trim(),if(name.text.trim().isEmpty)'search':search.text,if(name.text.trim().isEmpty)'replace':replace.text});}Future<void>pin(bool top)async{for(final id in parsed){await DioClient.instance.dio.put(top?ApiEndpoints.envMoveTop(id):ApiEndpoints.envCancelTop(id));}}Future<void>export()async{final r=await DioClient.instance.dio.post(ApiEndpoints.envsExportFiles,data:{'format':'all','ids':parsed});if(mounted)setState(()=>output=(r.data is Map?r.data['data']:r.data).toString());}@override void dispose(){ids.dispose();name.dispose();search.dispose();replace.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(backgroundColor:Colors.transparent,appBar:AppBar(title:const Text('环境变量高级工具')),body:ListView(padding:const EdgeInsets.all(20),children:[AppCard(child:Column(children:[TextField(controller:ids,decoration:const InputDecoration(labelText:'变量 ID，逗号分隔')),TextField(controller:name,decoration:const InputDecoration(labelText:'统一新名称')),TextField(controller:search,decoration:const InputDecoration(labelText:'查找文本')),TextField(controller:replace,decoration:const InputDecoration(labelText:'替换文本')),Wrap(spacing:8,children:[TextButton(onPressed:rename,child:const Text('批量改名')),TextButton(onPressed:()=>pin(true),child:const Text('置顶')),TextButton(onPressed:()=>pin(false),child:const Text('取消置顶')),TextButton(onPressed:export,child:const Text('多格式导出'))])])),if(output.isNotEmpty)AppCard(child:SelectableText(output,style:const TextStyle(fontFamily:'monospace')))]));}
